descriptor.templateCss:
.bess-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  transition: border-top-color 0.4s ease;
}

.bess-card-container.discharging {
  border-top-color: #f7d048;
}

.bess-card-container.standby {
  border-top-color: #94a3b8;
}

.bess-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
}

.bess-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
  white-space: nowrap;
}

.bess-icon {
  font-size: 16px;
}

.bess-status-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.bess-status-badge.charging {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.08);
}

.bess-status-badge.discharging {
  color: #f7d048;
  border: 1.5px solid #f59e0b;
  background: rgba(247, 208, 72, 0.08);
}

.bess-status-badge.standby {
  color: #94a3b8;
  border: 1.5px solid #94a3b8;
  background: rgba(148, 163, 184, 0.08);
}

.bess-metric-body {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 6px 0;
  min-height: 40px;
}

.metric-value {
  font-size: 40px;
  font-weight: 800;
  color: #64B856;
  line-height: 1;
}

.metric-unit {
  font-size: 20px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

.bess-divider {
  width: 100%;
  height: 1px;
  background: rgba(148, 163, 184, 0.15);
  margin: 8px 0 10px 0;
}

.bess-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  min-height: 38px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.footer-left .footer-label {
  font-size: 13px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
}

.footer-left .footer-subtext {
  font-size: 12px;
  color: #556987;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.footer-right {
  display: flex;
  align-items: flex-end;
}

.footer-right .footer-value {
  font-size: 16px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: color 0.3s ease;
}

.footer-right .footer-value.charging {
  color: #64B856;
}

.footer-right .footer-value.discharging {
  color: #f7d048;
}

.footer-right .footer-value.standby {
  color: #94a3b8;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var socVal = "97";
  var rawPowerVal = 17.1;
  var isPowerProvided = false;
  var deltaSoc = 0;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var keyName = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        var points = item.data;
        var lastVal = points[points.length - 1][1];

        if (keyName.indexOf("soc") !== -1 || i === 0) {
          var numSoc = parseFloat(lastVal);
          socVal = !isNaN(numSoc) ? Math.round(numSoc).toString() : lastVal;

          // Calcular si la tendencia del SOC es alza o baja comparando con el historial reciente
          if (points.length >= 2) {
            var currentPoint = parseFloat(points[points.length - 1][1]);
            for (var p = points.length - 2; p >= 0; p--) {
              var prevPoint = parseFloat(points[p][1]);
              if (!isNaN(prevPoint) && Math.abs(currentPoint - prevPoint) >= 0.05) {
                deltaSoc = currentPoint - prevPoint;
                break;
              }
            }
          }
        } else if (keyName.indexOf("power") !== -1 || keyName.indexOf("potencia") !== -1 || i === 1) {
          var numPower = parseFloat(lastVal);
          if (!isNaN(numPower)) {
            rawPowerVal = numPower;
            isPowerProvided = true;
          }
        }
      }
    }
  }

  // Determinar modo de operación
  var isCharging = true;
  var isStandby = false;

  if (isPowerProvided && Math.abs(rawPowerVal) < 0.1) {
    isStandby = true;
  } else if (isPowerProvided && rawPowerVal < 0) {
    // Si la telemetría entrega potencia negativa en descarga
    isCharging = false;
  } else if (deltaSoc < -0.05) {
    // Tendencia clara a la baja del SOC
    isCharging = false;
  } else if (deltaSoc > 0.05) {
    // Tendencia clara al alza del SOC
    isCharging = true;
  } else {
    // Fallback por defecto según el valor de potencia
    isCharging = rawPowerVal >= 0;
  }

  var modeClass = isStandby ? "standby" : (isCharging ? "charging" : "discharging");
  var statusLabel = isStandby ? "EN ESPERA" : (isCharging ? "CARGANDO" : "DESCARGANDO");
  var arrowIcon = isStandby ? "●" : (isCharging ? "▲" : "▼");
  var powerString = arrowIcon + " " + Math.abs(rawPowerVal).toFixed(1) + " kW";

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var card = container.querySelector('#bess-card');
    if (card) {
      card.className = "bess-card-container " + modeClass;
    }

    var elSoc = container.querySelector('#bess-soc-value');
    if (elSoc) elSoc.textContent = socVal;

    var elBadge = container.querySelector('#bess-status-badge');
    if (elBadge) {
      elBadge.textContent = statusLabel;
      elBadge.className = "bess-status-badge " + modeClass;
    }

    var elPower = container.querySelector('#bess-power-value');
    if (elPower) {
      elPower.textContent = powerString;
      elPower.className = "footer-value " + modeClass;
    }
  }
};

self.onDestroy = function() {};
